use serde::Deserialize;

/// Generated by the NixOS module (nix/locked/executor.nix). Not editable by the agent.
#[derive(Debug, Clone, Deserialize)]
pub struct Config {
    /// Unix user the agent runs as; the only uid accepted on the action socket.
    pub agent_user: String,
    /// Unix user of the HUD gateway; accepted on the approval socket (with root).
    pub hud_user: String,
    pub exec_socket: String,
    pub approve_socket: String,
    pub audit_path: String,
    /// Root-owned JSON file describing the active engagement. May be absent.
    pub engagement_path: String,
    /// Addresses that are never a valid target, whatever the engagement says.
    #[serde(default)]
    pub permanent_deny: Vec<String>,
    pub systemctl: String,
    pub journalctl: String,
    /// Units the agent may never restart (the locked core).
    #[serde(default)]
    pub forbidden_units: Vec<String>,
    #[serde(default = "default_ttl")]
    pub approval_ttl_ms: u64,
}

fn default_ttl() -> u64 {
    10 * 60 * 1000
}

impl Config {
    pub fn load(path: &str) -> Result<Config, String> {
        let text = std::fs::read_to_string(path).map_err(|e| format!("read {path}: {e}"))?;
        serde_json::from_str(&text).map_err(|e| format!("parse {path}: {e}"))
    }
}
